// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function testFuzz_property(uint256 newVal, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(newVal != c.MinSum());

        c.SetLogFile(address(this));
        c.SetMinSum(1);
        c.Initialized();

        uint256 before = c.MinSum();
        bool ok;
        vm.prank(actor);
        try c.SetMinSum(newVal) {
            ok = true;
        } catch {
            ok = false;
        }

        // After initialization, SetMinSum must never alter MinSum.
        assertTrue(c.MinSum() == before);
    }
}
